/* From Uiverse.io by aadium - Tags: cyberpunk, radio, futuristic */
.__UIV_SCOPE__ .container input[type="radio"] {
  position: absolute;
  opacity: 0;
  cursor: pointer;
  height: 0;
  width: 0;
}

.__UIV_SCOPE__ .container {
  display: inline-block;
  position: relative;
  cursor: pointer;
  font-size: 17px;
  width: 5em;
  height: 2.5em;
  user-select: none;
  border: none;
}

.__UIV_SCOPE__ .selected {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ #leftradio {
  border-bottom-left-radius: 2.5em;
  border-top-left-radius: 2.5em;
  border-bottom-right-radius: 0;
  border-top-right-radius: 0;
  border: 3px solid #78cce2;
  background-color: transparent;
  transition: 0.2s ease-in;
}

.__UIV_SCOPE__ #rightradio {
  border-bottom-right-radius: 2.5em;
  border-top-right-radius: 2.5em;
  border-bottom-left-radius: 0;
  border-top-left-radius: 0;
  border: 3px solid #defe47;
  background-color: transparent;
  transition: 0.2s linear;
}

.__UIV_SCOPE__ #middleradio {
  border: 3px solid #f887ff;
  background-color: transparent;
  transition: 0.2s linear;
}

.__UIV_SCOPE__ .selected:after {
  content: '';
  position: absolute;
  background-color: 78cce2;
  width: 100%;
  height: 90%;
  transform: scale(0);
  transition: 0.2s ease-out;
}

.__UIV_SCOPE__ #leftradio:hover {
  border-bottom-left-radius: 2.5em;
  border-top-left-radius: 2.5em;
  border-bottom-right-radius: 0;
  border-top-right-radius: 0;
  border: 3px solid #78cce2;
  background-color: #78cce2;
}

.__UIV_SCOPE__ #leftradio::after {
  top: 0%;
  height: 100%;
  border-bottom-left-radius: 2.5em;
  border-top-left-radius: 2.5em;
  border-bottom-right-radius: 0;
  border-top-right-radius: 0;
  border: none;
  background-color: #78cce2;
  box-shadow: 0em 0em 4em 0.1em #78cce2;
}

.__UIV_SCOPE__ #rightradio:hover {
  border-bottom-right-radius: 2.5em;
  border-top-right-radius: 2.5em;
  border-bottom-left-radius: 0;
  border-top-left-radius: 0;
  border: 3px solid #defe47;
  background-color: #defe47;
}

.__UIV_SCOPE__ #rightradio::after {
  left: -3%;
  top: -1%;
  border-bottom-right-radius: 2.5em;
  border-top-right-radius: 2.5em;
  border-bottom-left-radius: 0;
  border-top-left-radius: 0;
  border: 3px solid #defe47;
  background-color: #defe47;
  box-shadow: 0em 0em 4em 0.1em #defe47;
}

.__UIV_SCOPE__ #middleradio:hover {
  border: 3px solid #f887ff;
  background-color: #f887ff;
}

.__UIV_SCOPE__ #middleradio::after {
  left: -3%;
  top: -3%;
  border: 3px solid #f887ff;
  background-color: #f887ff;
  box-shadow: 0em 0em 4em 0.1em #f887ff;
}

.__UIV_SCOPE__ .container input[type="radio"]:checked ~ .selected:after {
  transform: scale(1);
}
